// Código atualizado para o node 'Code' no n8n
const array1 = $('Buffer: 1a Leitura').first()?.json?.Memory1;
const array2 = $('Buffer: 2a Leitura').first()?.json?.Memory2;

// Combina os elementos dos arrays em strings únicas (com proteção contra null/undefined)
const CombinedText1 = Array.isArray(array1) ? array1.join(' ') : (array1 ?? '');
const CombinedText2 = Array.isArray(array2) ? array2.join(' ') : (array2 ?? '');

// Retorna os resultados no formato exigido pelo n8n
return [
  {
    json: {
      CombinedText1,
      CombinedText2,
    },
  },
];

// Obtém a variável de entrada
const inputText = $('Loop de Mensagens').first().json.output;

// Verifica se a entrada é válida
if (typeof inputText !== 'string') {
    throw new Error('A entrada $input.first().json.message deve ser uma string.');
}

// Conta o número de caracteres
const charCount = inputText.length;

// Calcula o delay baseado em blocos de 40 caracteres
const result = Math.floor(charCount / 30) * 1000;

// Retorna os valores
return {
    characterCount: charCount,
    delay: result,
};

const text = $input.first().json.output;

// Substitui \n literais por quebras reais
const normalizedText = text.replace(/\\n/g, '\n');

// Divide por blocos de parágrafos
const parts = normalizedText.split(/\n{2,}/);

const results = [];

for (const part of parts) {
  // Regex para links que começam com https:// e terminam com extensão de mídia
  const urlRegex = /(https:\/\/\S+\.(?:mp4|png|webp|jpg|jpeg|mp3|ogg|pdf|docx|xlsx|doc))/gi;

  // Extrai os links
  const links = [...part.matchAll(urlRegex)].map(match => match[1]);

  // Remove todos os links do texto original
  const cleanedText = part.replace(urlRegex, '').trim();

  // Adiciona texto limpo, se houver
  if (cleanedText.length > 0) {
    results.push({ json: { output: cleanedText } });
  }

  // Adiciona cada link individualmente
  for (const link of links) {
    results.push({ json: { output: link } });
  }
}

return results;
